private List<AiImageDO> selectByStatusAndPlatform() {
    List<AiImageDO> imageList = imageMapper.selectList(new LambdaUpdateWrapper<AiImageDO>().eq(AiImageDO::getStatus, AiImageStatusEnum.IN_PROGRESS.getStatus()).eq(AiImageDO::getPlatform, AiPlatformEnum.MIDJOURNEY.getPlatform()));
    return imageList;
}
